def scoreboardTotal(ops):
    stack = []
    for op in ops:
        if op >= 0:
            stack.append(op)
        elif op == -1:
            stack.pop()
        elif op == -2:
            stack.append(2 * stack[-1])
        else:
            stack.append(stack[-1] + stack[-2])
    return sum(stack)
